scenarios.applySource:
assert(
  .status == "admitted" and
  .severity == "Moderate" and
  .vitals.heartRate == 94 and
  .vitals.bpSystolic == 138 and
  .vitals.bpDiastolic == 88;
  "Apply unavailable: the patient is not at the admitted rhythm-control baseline"
);
.vitals.bpSystolic = 168;
.vitals.bpDiastolic = 104;
.vitals.heartRate = 132;
.vitals.oxygenSaturation = 91;
.severity = "Critical";
.careSummary = "Rapid atrial fibrillation with hypoxemia. Begin continuous telemetry, oxygen support, and urgent cardiology review.";
append(
  .auditTrail;
  {
    occurredAt: "2026-09-01 10:12",
    actor: "Jordan Blake, RN",
    action: "Escalated acute rhythm-control event to critical"
  }
);

scenarios.resetSource:
assert(
  .severity == "Critical" and
  .vitals.heartRate == 132 and
  .vitals.bpSystolic == 168;
  "Reverse unavailable: the acute rhythm-control escalation is not currently applied"
);
.vitals.bpSystolic = 138;
.vitals.bpDiastolic = 88;
.vitals.heartRate = 94;
.vitals.oxygenSaturation = 97;
.severity = "Moderate";
.careSummary = "Rate control is improving. Continue telemetry, anticoagulation monitoring, and assisted ambulation twice daily.";
del(
  .auditTrail[* .occurredAt == "2026-09-01 10:12"]
);

scenarios.applySource:
assert(
  (.medications[] | select(.name == "Warfarin") | .doseMg) == 5 and
  (.medications[] | select(.name == "Warfarin") | .lastDoseStatus) == "Administered";
  "Apply unavailable: Warfarin must be at the 5 mg administered baseline"
);
(
  .medications[]
  | select(.name == "Warfarin")
  | .doseMg
) |= . + 2.5;
(
  .medications[]
  | select(.name == "Warfarin")
  | .lastDoseStatus
) = "Held — INR review";
append(
  .internalNotes;
  {
    authoredAt: "2026-09-01 10:20",
    author: "Dr. Aisha Tahir",
    category: "Anticoagulation",
    text: "Warfarin titrated to 7.5 mg; next dose held pending repeat INR."
  }
);

scenarios.resetSource:
assert(
  (.medications[] | select(.name == "Warfarin") | .doseMg) == 7.5 and
  (.medications[] | select(.name == "Warfarin") | .lastDoseStatus) == "Held — INR review";
  "Reverse unavailable: the Warfarin titration and dose hold are not currently applied"
);
(
  .medications[]
  | select(.name == "Warfarin")
  | .doseMg
) = 5;
(
  .medications[]
  | select(.name == "Warfarin")
  | .lastDoseStatus
) = "Administered";
del(
  .internalNotes[* .authoredAt == "2026-09-01 10:20"]
);

scenarios.applySource:
assert(
  any(.medications[]; .lastDoseStatus == "Administered");
  "Apply unavailable: there are no administered medications to place on transfer hold"
);
(
  .medications[* .lastDoseStatus == "Administered"]
  | .lastDoseStatus
) = "Transfer hold";
append(
  .auditTrail;
  {
    occurredAt: "2026-09-01 10:28",
    actor: "Elena Ruiz, PharmD",
    action: "Placed all administered medications on transfer hold"
  }
);

scenarios.resetSource:
assert(
  any(.medications[]; .lastDoseStatus == "Transfer hold");
  "Reverse unavailable: no medications are currently on transfer hold"
);
(
  .medications[* .lastDoseStatus == "Transfer hold"]
  | .lastDoseStatus
) = "Administered";
del(
  .auditTrail[* .occurredAt == "2026-09-01 10:28"]
);

scenarios.applySource:
assert(
  .billing.procedures == 4200 and
  .billing.pharmacy == 310;
  "Apply unavailable: billing has changed from the expected pre-charge baseline"
);
.billing.procedures |= . + 2850;
.billing.pharmacy |= . + 640;
append(
  .auditTrail;
  {
    occurredAt: "2026-09-01 10:35",
    actor: "Northstar Billing Interface",
    action: "Posted cardioversion procedure and anticoagulation pharmacy charges"
  }
);

scenarios.resetSource:
assert(
  .billing.procedures == 7050 and
  .billing.pharmacy == 950;
  "Reverse unavailable: the cardioversion and pharmacy charges are not currently posted"
);
.billing.procedures = 4200;
.billing.pharmacy = 310;
del(
  .auditTrail[* .occurredAt == "2026-09-01 10:35"]
);

scenarios.applySource:
assert(
  all(.caretakerInstructions[]; .activity != "Fall precautions");
  "Apply unavailable: fall precautions are already present in the care plan"
);
insert_item_after(
  {
    activity: "Fall precautions",
    status: "High risk",
    instruction: "Use gait belt and two-person assist until orthostatic symptoms resolve.",
    schedule: "Every transfer"
  };
  .caretakerInstructions[]
  | select(.activity == "Mobility")
);

scenarios.resetSource:
assert(
  any(.caretakerInstructions[]; .activity == "Fall precautions");
  "Reverse unavailable: fall precautions are not present in the care plan"
);
del(
  .caretakerInstructions[* .activity == "Fall precautions"]
);

scenarios.applySource:
assert(
  .caretakerInstructions[0].activity == "Meals" and
  .caretakerInstructions[3].activity == "Mobility";
  "Apply unavailable: daily care is not in the expected baseline order"
);
move_item_before(
  .caretakerInstructions[] | select(.activity == "Mobility");
  .caretakerInstructions[] | select(.activity == "Meals")
);

scenarios.resetSource:
assert(
  .caretakerInstructions[0].activity == "Mobility";
  "Reverse unavailable: Mobility is not currently the first care priority"
);
reorder_by(
  .caretakerInstructions;
  .activity;
  ["Meals", "Feeding", "Bathroom", "Mobility"]
);

scenarios.applySource:
assert(
  .dischargeSummaryDraft == null;
  "Apply unavailable: a discharge-summary draft already exists"
);
copy_value_to(
  .careSummary;
  .dischargeSummaryDraft
);
.dischargeSummaryDraft |= . + " Discharge when rate remains controlled for 24 hours; arrange INR follow-up within 48 hours.";

scenarios.resetSource:
assert(
  .dischargeSummaryDraft != null;
  "Reverse unavailable: there is no discharge-summary draft to clear"
);
.dischargeSummaryDraft = null;

