assert(
  any(.consultingClinicians[]; .id == "https://localhost:4251/bxl-clinical-mutation/Principal/amara-shah") and
  any(.consultingClinicians[]; .id == "https://localhost:4251/bxl-clinical-mutation/Principal/jordan-blake");
