move_item_before(
  .consultingClinicians[]
  | select(.id == "https://localhost:4251/bxl-clinical-mutation/Principal/elena-ruiz");
  .consultingClinicians[]
  | select(.id == "https://localhost:4251/bxl-clinical-mutation/Principal/theo-martin")
);

